package org.buddycloud.channelserver.packetprocessor.iq;

import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.BlockingQueue;

import org.apache.log4j.Logger;
import org.buddycloud.channelserver.Configuration;
import org.buddycloud.channelserver.channel.ChannelManager;
import org.buddycloud.channelserver.packetprocessor.PacketProcessor;
import org.buddycloud.channelserver.packetprocessor.iq.namespace.discoinfo.JabberDiscoInfo;
import org.buddycloud.channelserver.packetprocessor.iq.namespace.discoitems.JabberDiscoItems;
import org.buddycloud.channelserver.packetprocessor.iq.namespace.mam.MessageArchiveManagement;
import org.buddycloud.channelserver.packetprocessor.iq.namespace.pubsub.JabberPubsub;
import org.buddycloud.channelserver.packetprocessor.iq.namespace.register.JabberRegister;
import org.buddycloud.channelserver.packetprocessor.iq.namespace.search.Search;
import org.buddycloud.channelserver.queue.FederatedQueueManager;
import org.buddycloud.channelserver.queue.UnknownFederatedPacketException;
import org.xmpp.packet.IQ;
import org.xmpp.packet.IQ.Type;
import org.xmpp.packet.Packet;
import org.xmpp.packet.PacketError;

public class IQProcessor implements PacketProcessor<IQ> {

	private static final Logger logger = Logger.getLogger(IQProcessor.class);

	private Map<String, PacketProcessor<IQ>> processorsPerNamespace = new HashMap<String, PacketProcessor<IQ>>();
	private BlockingQueue<Packet> outQueue;
	private FederatedQueueManager federatedQueueManager;

	public IQProcessor(BlockingQueue<Packet> outQueue, Configuration conf,
			ChannelManager channelManager,
			FederatedQueueManager federatedQueueManager) {
		this.outQueue = outQueue;
		this.federatedQueueManager = federatedQueueManager;

		JabberPubsub ps = new JabberPubsub(outQueue, conf, channelManager,
				federatedQueueManager);

		processorsPerNamespace.put(JabberDiscoItems.NAMESPACE_URI,
				new JabberDiscoItems(outQueue, conf, channelManager,
						federatedQueueManager));
		processorsPerNamespace.put(JabberDiscoInfo.NAMESPACE_URI,
				new JabberDiscoInfo(outQueue, conf, channelManager,
						federatedQueueManager));
		processorsPerNamespace.put(JabberRegister.NAMESPACE_URI,
				new JabberRegister(outQueue, conf, channelManager));
		processorsPerNamespace.put(JabberPubsub.NAMESPACE_URI, ps);
		processorsPerNamespace.put(JabberPubsub.NS_PUBSUB_OWNER, ps);
		processorsPerNamespace.put(MessageArchiveManagement.NAMESPACE_MAM,
				new MessageArchiveManagement(outQueue, channelManager));
		processorsPerNamespace.put(Search.NAMESPACE_URI,
		        new Search(outQueue, channelManager));
	}

	@Override
	public void process(IQ packet) throws Exception {

		try {
			processPacket(packet);
		} catch (Exception e) {
			if (true == packet.getType().toString().equals("result")) return;
			IQ reply = IQ.createResultIQ(packet);
			reply.setChildElement(packet.getChildElement().createCopy());
			reply.setType(Type.error);
			PacketError pe = new PacketError(
					org.xmpp.packet.PacketError.Condition.internal_server_error,
					org.xmpp.packet.PacketError.Type.wait);
			reply.setError(pe);
			logger.error("Error while processing packet.", e);
            e.printStackTrace();
			this.outQueue.put(reply);
		}
	}

	private void processPacket(IQ packet) throws Exception,
			InterruptedException {
		if (null != packet.getChildElement()) {
			logger.debug("Finding IQ processor for namespace "
					+ packet.getChildElement().getNamespaceURI());

			PacketProcessor<IQ> namespaceProcessor = processorsPerNamespace
					.get(packet.getChildElement().getNamespaceURI());

			if (packet.getChildElement().getNamespaceURI() != null
					&& namespaceProcessor != null) {
				logger.trace("Using namespace processor: "
						+ namespaceProcessor.getClass().getName());
				namespaceProcessor.process(packet);
				return;

			}
		}
		// See if this was an externally sent packet
		try {
			federatedQueueManager.passResponseToRequester(packet);
			return;
		} catch (UnknownFederatedPacketException e) {
			logger.error(e);
		}
		logger.debug("Couldn't find processor for packet");

		if (packet.getType() == IQ.Type.set || packet.getType() == IQ.Type.get) {

			IQ reply = IQ.createResultIQ(packet);
			reply.setChildElement(packet.getChildElement().createCopy());
			reply.setType(Type.error);
			PacketError pe = new PacketError(
					org.xmpp.packet.PacketError.Condition.service_unavailable,
					org.xmpp.packet.PacketError.Type.cancel);
			reply.setError(pe);

			this.outQueue.put(reply);
			return;

		}
		logger.error("Could not handle packet " + packet.toXML());
	}
}

package org.buddycloud.channelserver.packetprocessor.iq.namespace.discoinfo;

import java.util.Map;
import java.util.TreeMap;
import java.util.concurrent.BlockingQueue;
import org.apache.log4j.Logger;
import org.buddycloud.channelserver.channel.ChannelManager;
import org.buddycloud.channelserver.packetprocessor.PacketProcessor;
import org.buddycloud.channelserver.packetprocessor.iq.namespace.pubsub.JabberPubsub;
import org.dom4j.Element;
import org.xmpp.forms.DataForm;
import org.xmpp.forms.FormField;
import org.xmpp.packet.IQ;
import org.xmpp.packet.IQ.Type;
import org.xmpp.packet.JID;
import org.xmpp.packet.Packet;
import org.xmpp.packet.PacketError;

public class DiscoInfoGet implements PacketProcessor<IQ> {

	public static final String ELEMENT_NAME = "query";
	private static final Logger logger = Logger.getLogger(DiscoInfoGet.class);
	private final BlockingQueue<Packet> outQueue;
	private final ChannelManager channelManager;
	private String node;
	private IQ result;
	private IQ requestIq;
	private Element query;
	private Map<String, String> conf;

	public DiscoInfoGet(BlockingQueue<Packet> outQueue, ChannelManager channelManager) {
		this.outQueue = outQueue;
		this.channelManager = channelManager;
	}

	@Override
	public void process(IQ reqIQ) throws Exception {

		requestIq     = reqIQ;
		result     = IQ.createResultIQ(reqIQ);
		Element elm   = reqIQ.getChildElement();
		node          = elm.attributeValue("node");
		query        = result.setChildElement(ELEMENT_NAME,
				JabberDiscoInfo.NAMESPACE_URI);
        if (false == channelManager.isLocalJID(requestIq.getFrom())) {
        	result.getElement().addAttribute("remote-server-discover", "false");
        }
		if ((node == null) || (true == node.equals(""))) {
			sendServerDiscoInfo();
			return;
		}
		if (false == channelManager.isLocalNode(node)
	        && (false == channelManager.isCachedNode(node))) {
			logger.info("Node " + node + " is remote and not cached so "
			    + "we're going off to get disco#info");
			makeRemoteRequest();
		    return;
		}
		conf = channelManager.getNodeConf(node);
		if (conf.isEmpty()) {
			nodeDoesntExistResponse();
			return;
		}
		sendNodeConfigurationInformation();
	}

	private void sendNodeConfigurationInformation() throws InterruptedException {

		TreeMap<String, String> sorted_conf = new TreeMap<String, String>();

		DataForm x = new DataForm(DataForm.Type.result);

		FormField formType = x.addField();
		formType.setType(FormField.Type.hidden);
		formType.setVariable("FORM_TYPE");
		formType.addValue("http://jabber.org/protocol/pubsub#meta-data");

		sorted_conf.putAll(conf);
		for (String key : sorted_conf.keySet()) {
			x.addField(key, null, null).addValue(sorted_conf.get(key));
		}

		query.addAttribute("node", node);
		query.addElement("identity").addAttribute("category", "pubsub")
				.addAttribute("type", "leaf");
		query.addElement("feature").addAttribute("var",
				"http://jabber.org/protocol/pubsub");

		query.add(x.getElement());

		query.addElement("feature").addAttribute("var", JabberPubsub.NAMESPACE_URI);
		Element identity = query.addElement("identity");
		identity.addAttribute("category", "pubsub");
		identity.addAttribute("type",  "leaf");

        logger.trace("Returning DISCO info for node: " + node);
		outQueue.put(result);
	}

	private void nodeDoesntExistResponse() throws InterruptedException {
		/*
		 * Not found. Let's return something like this: <iq type='error'
		 * from='plays.shakespeare.lit' to='romeo@montague.net/orchard'
		 * id='info1'> <query xmlns='http://jabber.org/protocol/disco#info'
		 * node='/user/pretty@lady.com/posts'/> <error type='cancel'>
		 * <item-not-found xmlns='urn:ietf:params:xml:ns:xmpp-stanzas'/>
		 * </error> </iq>
		 */

		result.setChildElement(result.getChildElement().createCopy());
		result.setType(Type.error);
		PacketError pe = new PacketError(
				org.xmpp.packet.PacketError.Condition.item_not_found,
				org.xmpp.packet.PacketError.Type.cancel);
		result.setError(pe);
		outQueue.put(result);
	}

	private void sendServerDiscoInfo()
			throws InterruptedException {
		query.addElement("identity").addAttribute("category", "pubsub")
				.addAttribute("type", "channels");

		query.addElement("identity").addAttribute("category", "pubsub")
				.addAttribute("type", "inbox");

		query.addElement("feature").addAttribute("var",
				"jabber:iq:register");

		query.addElement("feature").addAttribute("var",
				"http://jabber.org/protocol/disco#info");

		query.addElement("feature").addAttribute("var",
				"http://jabber.org/protocol/disco#items");

		query.addElement("feature").addAttribute("var",
				"jabber:iq:search");

		outQueue.put(result);
	}

	private void makeRemoteRequest() throws InterruptedException {
		requestIq.setTo(new JID(node.split("/")[2]).getDomain());
	    outQueue.put(requestIq);
	}
}

