import org.openqa.selenium.Dimension;
import org.openqa.selenium.JavascriptExecutor;
import org.openqa.selenium.Point;
import org.openqa.selenium.WebDriver;

import java.util.Arrays;
import java.util.HashSet;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.reset;
import static org.mockito.Mockito.spy;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

@RunWith(MockitoJUnitRunner.class)
public class WindowActionsTest {
    @Mock
    private WebDriver driver;
    @Mock
    private WebDriver.Window window;
    @Mock
    private WebDriver.Options options;
    @Mock
    private FluentDriver fluentDriver;
    @Mock
    private FluentControl fluentControl;
    @Mock
    private ComponentInstantiator instantiator;
    @Mock
    private WebDriver.TargetLocator targetLocator;

    @Before
    public void before() {
        when(fluentDriver.getDriver()).thenReturn(driver);
        when(driver.manage()).thenReturn(options);
        when(driver.manage().window()).thenReturn(window);
        when(driver.switchTo()).thenReturn(targetLocator);
        when(driver.switchTo().window(any())).thenReturn(driver);
    }

    @After
    public void after() {
        reset(driver, window, fluentDriver);
    }

    @Test
    public void getWindowTest() {
        WindowAction windowAction = new WindowAction(fluentDriver, instantiator, driver);

        windowAction.getWindow();
        verify(driver.manage(), times(1)).window();
    }

    @Test
    public void maximizeWindowTest() {
        WindowAction windowAction = new WindowAction(fluentDriver, instantiator, driver);

        windowAction.maximize();
        verify(driver.manage(), times(1)).window();
        verify(driver.manage().window(), times(1)).maximize();
    }

    @Test
    public void fullScreenWindowTest() {
        WindowAction windowAction = new WindowAction(fluentDriver, instantiator, driver);

        windowAction.fullscreen();
        verify(driver.manage(), times(1)).window();
        verify(driver.manage().window(), times(1)).fullscreen();
    }

    @Test
    public void switchToTargetLocatorTest() {
        WindowAction windowAction = new WindowAction(fluentDriver, instantiator, driver);

        FluentTargetLocator<WindowAction> switchTargetLocator = windowAction.switchTo();
        assertThat(switchTargetLocator).isNotNull();

        switchTargetLocator.parentFrame();
    }

    @Test
    public void switchToTest() {
        String windowHandle = "WndH1";

        WindowAction windowAction = new WindowAction(fluentDriver, instantiator, driver);

        when(driver.getWindowHandle()).thenReturn(windowHandle);

        windowAction.switchTo(windowHandle);

        verify(driver, times(1)).manage();
        verify(driver, times(2)).switchTo();
    }

    @Test
    public void switchToLast() {
        String windowHandle = "WndH1";
        String windowHandle2 = "WndH2";

        WindowAction windowAction = new WindowAction(fluentDriver, instantiator, driver);

        when(driver.getWindowHandles()).thenReturn(new HashSet<>(Arrays.asList(windowHandle, windowHandle2)));

        windowAction.switchToLast();

        verify(driver, times(1)).manage();
        verify(driver, times(2)).switchTo();
    }

    @Test
    public void openNewAndSwitch() {
        JavascriptWebDriver jsDriver = mock(JavascriptWebDriver.class);

        when(fluentDriver.getDriver()).thenReturn(jsDriver);
        when(jsDriver.switchTo()).thenReturn(targetLocator);
        when(jsDriver.switchTo().window(any())).thenReturn(driver);

        String windowHandle = "WndH1";
        String windowHandle1 = "WndH2";
        String windowHandle2 = "WndH3";

        Configuration configuration = mock(Configuration.class);

        FluentDriver currentFluentDriver = new FluentDriver(driver, configuration, fluentControl);
        FluentDriver fluentDriverSpied = spy(currentFluentDriver);

        when(jsDriver.getWindowHandles()).thenReturn(new HashSet<>(Arrays.asList(windowHandle, windowHandle1)),
                new HashSet<>(Arrays.asList(windowHandle, windowHandle1, windowHandle2)));
        when(jsDriver.getWindowHandle()).thenReturn(windowHandle1, windowHandle2);

        WindowAction windowAction = new WindowAction(fluentDriverSpied, instantiator, jsDriver);
        windowAction.openNewAndSwitch();

        verify(jsDriver, times(1)).getWindowHandle();
        verify(jsDriver, times(3)).getWindowHandles();
        verify(jsDriver, times(2)).switchTo();

    }

    @Test
    public void switchToParentFrame() {
        WindowAction windowAction = new WindowAction(fluentDriver, instantiator, driver);

        windowAction.switchTo().parentFrame();

        verify(driver, times(1)).manage();
        verify(driver.switchTo(), times(1)).parentFrame();
    }

    @Test
    public void setSizeTest() {
        WindowAction windowAction = new WindowAction(fluentDriver, instantiator, driver);
        Dimension dim = new Dimension(100, 200);
        windowAction.setSize(dim);
        verify(driver.manage(), times(1)).window();
        verify(driver.manage().window(), times(1)).setSize(eq(dim));
    }

    @Test
    public void clickAndCloseCurrentTest() throws InterruptedException {
        String windowHandle = "WndH1";
        String windowHandle2 = "WndH2";

        FluentWebElement fluentWebElement = mock(FluentWebElement.class);
        FluentWait fluentWait = mock(FluentWait.class);
        FluentWaitWindowConditions fluentWaitWindowMatcher = mock(FluentWaitWindowConditions.class);

        when(driver.getWindowHandles()).thenReturn(new HashSet<>(Arrays.asList(windowHandle, windowHandle2)));
        when(fluentWaitWindowMatcher.notDisplayed()).thenReturn(true);
        when(fluentWebElement.click()).thenReturn(fluentWebElement);
        when(fluentWait.untilWindow(any())).thenReturn(fluentWaitWindowMatcher);
        when(fluentDriver.await()).thenReturn(fluentWait);

        WindowAction windowAction = new WindowAction(fluentDriver, instantiator, driver);
        windowAction.clickAndCloseCurrent(fluentWebElement);

        verify(driver, times(1)).manage();
        verify(driver, times(1)).getWindowHandle();

    }

    @Test
    public void clickAndOpenNewTest() throws InterruptedException {
        String windowHandle = "WndH1";
        String windowHandle1 = "WndH2";
        String windowHandle2 = "WndH3";

        FluentWebElement fluentWebElement = mock(FluentWebElement.class);
        FluentWait fluentWait = mock(FluentWait.class);
        FluentWaitWindowConditions fluentWaitWindowMatcher = mock(FluentWaitWindowConditions.class);
        Configuration configuration = mock(Configuration.class);

        FluentDriver currentFluentDriver = new FluentDriver(driver, configuration, fluentControl);
        FluentDriver fluentDriverSpy = spy(currentFluentDriver);

        when(driver.getWindowHandles()).thenReturn(new HashSet<>(Arrays.asList(windowHandle, windowHandle1)),
                new HashSet<>(Arrays.asList(windowHandle, windowHandle1, windowHandle2)));
        when(driver.getWindowHandle()).thenReturn(windowHandle1, windowHandle2);

        when(fluentWebElement.click()).thenReturn(fluentWebElement);

        WindowAction windowAction = new WindowAction(fluentDriverSpy, instantiator, driver);
        windowAction.clickAndOpenNew(fluentWebElement);

        verify(driver, times(3)).manage();
        verify(driver, times(3)).getWindowHandles();
    }

    @Test
    public void getSizeTest() {
        WindowAction windowAction = new WindowAction(fluentDriver, instantiator, driver);
        Point pos = new Point(101, 201);

        when(driver.manage().window().getPosition()).thenReturn(pos);

        Point getPos = windowAction.getPosition();

        verify(driver.manage(), times(2)).window();
        verify(driver.manage().window(), times(1)).getPosition();
        assertThat(getPos).isEqualTo(pos);
    }

    @Test
    public void getPositionTest() {
        WindowAction windowAction = new WindowAction(fluentDriver, instantiator, driver);
        Dimension dim = new Dimension(101, 201);

        when(driver.manage().window().getSize()).thenReturn(dim);

        Dimension getSizeDim = windowAction.getSize();

        verify(driver.manage(), times(2)).window();
        verify(driver.manage().window(), times(1)).getSize();
        assertThat(getSizeDim).isEqualTo(dim);
    }

    @Test
    public void setPositionTest() {
        WindowAction windowAction = new WindowAction(fluentDriver, instantiator, driver);
        Point pos = new Point(101, 201);

        windowAction.setPosition(pos);
        verify(driver.manage(), times(1)).window();
        verify(driver.manage().window(), times(1)).setPosition(eq(pos));
    }

    @Test
    public void titleTest() {
        String title = "title";
        WindowAction windowAction = new WindowAction(fluentDriver, instantiator, driver);
        when(driver.getTitle()).thenReturn(title);

        assertThat(windowAction.title()).isEqualTo(title);

        verify(driver.manage(), times(0)).window();
    }

    public interface JavascriptWebDriver extends WebDriver, JavascriptExecutor {

    }
}

package org.fluentlenium.core.conditions;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.Mockito.reset;
import static org.mockito.Mockito.when;

import java.util.Arrays;
import java.util.Collections;

import org.junit.After;
import org.junit.Before;
import org.junit.Test;
import org.openqa.selenium.StaleElementReferenceException;

public class AtLeastOneElementConditionsTest extends AbstractFluentListConditionsTest {
    private AtLeastOneElementConditions conditions;

    @Before
    public void before() {
        super.before();
        conditions = new AtLeastOneElementConditions(Arrays.asList(fluentWebElement1, fluentWebElement2, fluentWebElement3));
    }

    @After
    public void after() {
        reset(webElement1);
        reset(webElement2);
        reset(webElement3);
    }

    @Test
    public void verify() {
        assertThat(conditions.verify(predicate -> true)).isTrue();
        assertThat(conditions.verify(predicate -> false)).isFalse();

        assertThat(conditions.not().verify(predicate -> true)).isFalse();
        assertThat(conditions.not().verify(predicate -> false)).isTrue();
    }

    @Test
    public void present() {
        assertThat(conditions.present()).isTrue();
        assertThat(conditions.not().present()).isFalse();

        AtLeastOneElementConditions emptyConditions = new AtLeastOneElementConditions(Collections.emptyList());

        assertThat(emptyConditions.present()).isFalse();
        assertThat(emptyConditions.not().present()).isTrue();
    }

    @Test
    public void clickable() {
        assertThat(conditions.clickable()).isFalse();

        when(webElement1.isEnabled()).thenReturn(true);
        when(webElement1.isDisplayed()).thenReturn(true);

        assertThat(conditions.clickable()).isTrue();
    }

    @Test
    public void stale() {
        assertThat(conditions.stale()).isFalse();

        // Selenium invokes isEnabled to check staleness.
        when(webElement2.isEnabled()).thenThrow(StaleElementReferenceException.class);

        assertThat(conditions.stale()).isTrue();
    }

    @Test
    public void enabled() {
        assertThat(conditions.enabled()).isFalse();

        when(webElement3.isEnabled()).thenReturn(true);

        assertThat(conditions.enabled()).isTrue();
    }

    @Test
    public void displayed() {
        assertThat(conditions.displayed()).isFalse();

        when(webElement1.isDisplayed()).thenReturn(true);

        assertThat(conditions.displayed()).isTrue();
    }

    @Test
    public void selected() {
        assertThat(conditions.selected()).isFalse();

        when(webElement2.isSelected()).thenReturn(true);

        assertThat(conditions.selected()).isTrue();
    }

    @Test
    public void text() {
        when(webElement3.getText()).thenReturn("Some Text");

        assertThat(conditions.text().contains("Some Text")).isTrue();
        assertThat(conditions.text().contains("Other Text")).isFalse();
    }

    @Test
    public void textContains() {
        when(webElement1.getText()).thenReturn("Some Text");

        assertThat(conditions.text().contains("Te")).isTrue();
        assertThat(conditions.text().contains("Other")).isFalse();
    }

    @Test
    public void attributeValue() {
        assertThat(conditions.attribute("attr", "value")).isFalse();

        when(webElement2.getAttribute("attr")).thenReturn("value");

        assertThat(conditions.attribute("attr", "value")).isTrue();
    }

    @Test
    public void attribute() {
        assertThat(conditions.attribute("attr").equalTo("value")).isFalse();

        when(webElement2.getAttribute("attr")).thenReturn("value");

        assertThat(conditions.attribute("attr").equalTo("value")).isTrue();
    }

    @Test
    public void idValue() {
        assertThat(conditions.id("value")).isFalse();

        when(webElement3.getAttribute("id")).thenReturn("value");

        assertThat(conditions.id("value")).isTrue();
    }

    @Test
    public void id() {
        assertThat(conditions.id().equalTo("value")).isFalse();

        when(webElement3.getAttribute("id")).thenReturn("value");

        assertThat(conditions.id().equalTo("value")).isTrue();
    }

    @Test
    public void nameValue() {
        assertThat(conditions.name("value")).isFalse();

        when(webElement1.getAttribute("name")).thenReturn("value");

        assertThat(conditions.name("value")).isTrue();
    }

    @Test
    public void name() {
        assertThat(conditions.name().equalTo("value")).isFalse();

        when(webElement1.getAttribute("name")).thenReturn("value");

        assertThat(conditions.name().equalTo("value")).isTrue();
    }

    @Test
    public void tagNameValue() {
        assertThat(conditions.tagName("value")).isFalse();

        when(webElement1.getTagName()).thenReturn("value");

        assertThat(conditions.tagName("value")).isTrue();
    }

    @Test
    public void tagName() {
        assertThat(conditions.tagName().equalTo("value")).isFalse();

        when(webElement1.getTagName()).thenReturn("value");

        assertThat(conditions.tagName().equalTo("value")).isTrue();
    }

    @Test
    public void valueValue() {
        assertThat(conditions.value("value")).isFalse();

        when(webElement1.getAttribute("value")).thenReturn("value");

        assertThat(conditions.value("value")).isTrue();
    }

    @Test
    public void value() {
        assertThat(conditions.value().equalTo("value")).isFalse();

        when(webElement1.getAttribute("value")).thenReturn("value");

        assertThat(conditions.value().equalTo("value")).isTrue();
    }

    @Test
    public void hasSize() {
        assertThat(conditions.size(3)).isTrue();
        assertThat(conditions.size().equalTo(3)).isTrue();
        assertThat(conditions.size(2)).isFalse();
        assertThat(conditions.size().equalTo(2)).isFalse();

        assertThat(conditions.not().size(3)).isFalse();
        assertThat(conditions.not().size().equalTo(3)).isFalse();
        assertThat(conditions.not().size(2)).isTrue();
        assertThat(conditions.not().size().equalTo(2)).isTrue();

        AtLeastOneElementConditions conditions2 = new AtLeastOneElementConditions(
                Arrays.asList(fluentWebElement1, fluentWebElement3));

        assertThat(conditions2.size(3)).isFalse();
        assertThat(conditions2.size().equalTo(3)).isFalse();
        assertThat(conditions2.size(2)).isTrue();
        assertThat(conditions2.size().equalTo(2)).isTrue();
    }

    @Test
    public void className() {
        when(webElement1.getAttribute("class")).thenReturn("some-class-1 some-class-3");
        when(webElement2.getAttribute("class")).thenReturn("some-class-1 some-class-2 some-class-3");
        when(webElement3.getAttribute("class")).thenReturn("some-class-1");

        assertThat(conditions.className("some-class-1")).isTrue();
        assertThat(conditions.className("some-class-2")).isTrue();
        assertThat(conditions.className("some-class-4")).isFalse();
    }

    @Test
    public void defaultValueWhenEmpty() {
        AtLeastOneElementConditions emptyConditions = new AtLeastOneElementConditions(Collections.emptyList());

        assertThat(emptyConditions.enabled()).isFalse();
    }
}

