        }

    }

    @Test(expected = CustomException3.class)
    public void testIgnoring2Negative() {

        try {
            await().atMost(1, TimeUnit.NANOSECONDS).ignoring(CustomException.class, CustomException2.class).until(() -> {
                throw new CustomException3();
