/**
 * A button is a {@link Table} with a checked state and additional
 * {@link ButtonStyle style} fields for pressed, unpressed, and checked. Each
 * time a button is clicked, the checked state is toggled. Being a table, a
 * button can contain any other actors.
 * <p>
 * {@link ChangeEvent} is fired when the button is clicked. Cancelling the event
 * will restore the checked button state to what is was previously.
 * <p>
 * The preferred size of the button is determined by the background and the
 * button contents.
 * 
 * @author Nathan Sweet
 */
public class UIButton extends Table implements Disableable {
    private ButtonStyle style;
    boolean isChecked, isDisabled;
    ButtonGroup buttonGroup;
    private ClickListener clickListener;

    Array<Drawable> overAnimation = new Array<Drawable>();
    float frameDuration;
    float stateDuration;
    int currentFrame;

    public UIButton(Skin skin) {
        super(skin);
        initialize();
        setStyle(skin.get(ButtonStyle.class));
        setSize(getPrefWidth(), getPrefHeight());
    }

    public UIButton(Skin skin, String styleName) {
        super(skin);
        initialize();
        setStyle(skin.get(styleName, ButtonStyle.class));
        setSize(getPrefWidth(), getPrefHeight());
    }

    public UIButton(Actor child, Skin skin, String styleName) {
        this(child, skin.get(styleName, ButtonStyle.class));
    }

    public UIButton(Actor child, ButtonStyle style) {
        initialize();
        add(child);
        setStyle(style);
        setSize(getPrefWidth(), getPrefHeight());
    }

    public UIButton(ButtonStyle style) {
        initialize();
        setStyle(style);
        setSize(getPrefWidth(), getPrefHeight());
    }

    /**
     * Creates a button without setting the style or size. At least a style must
     * be set before using this button.
     */
    public UIButton() {
        initialize();
    }

    private void initialize() {
        setTouchable(Touchable.enabled);
        addListener(clickListener = new ClickListener() {
            public void clicked(InputEvent event, float x, float y) {
                if (isDisabled)
                    return;
                setChecked(!isChecked);
            }
        });
    }

    public UIButton(Drawable up) {
        this(new ButtonStyle(up, null, null));
    }

    public UIButton(Drawable up, Drawable down) {
        this(new ButtonStyle(up, down, null));
    }

    public UIButton(Drawable up, Drawable down, Drawable checked) {
        this(new ButtonStyle(up, down, checked));
    }

    public UIButton(Actor child, Skin skin) {
        this(child, skin.get(ButtonStyle.class));
    }

    public void setChecked(boolean isChecked) {
        if (this.isChecked == isChecked)
            return;
        // if (buttonGroup != null && !buttonGroup.canCheck(this, isChecked))
        // return;
        this.isChecked = isChecked;
        ChangeEvent changeEvent = Pools.obtain(ChangeEvent.class);
        if (fire(changeEvent))
            this.isChecked = !isChecked;
        Pools.free(changeEvent);
    }

    public void setOverAnimation(Skin skin, String filename, float frameDuration) {
        Array<AtlasRegion> regions = skin.getAtlas().findRegions(filename);
        for (AtlasRegion atlasRegion : regions) {
            Drawable drawable = new TextureRegionDrawable(skin.getAtlas()
                    .createSprite(atlasRegion.name, atlasRegion.index));
            overAnimation.add(drawable);
        }
        this.frameDuration = frameDuration;
        currentFrame = 0;
    }

    @Override
    public void act(float delta) {
        // TODO Auto-generated method stub
        super.act(delta);
        if (overAnimation.size > 0 && stateDuration >= frameDuration) {
            currentFrame = (currentFrame + 1) % overAnimation.size;
            stateDuration = 0f;
        }

        stateDuration += delta;
    }

    /**
     * Toggles the checked state. This method changes the checked state, which
     * fires a {@link ChangeEvent}, so can be used to simulate a button click.
     */
    public void toggle() {
        setChecked(!isChecked);
    }

    public boolean isChecked() {
        return isChecked;
    }

    public boolean isPressed() {
        return clickListener.isVisualPressed();
    }

    public boolean isOver() {
        return clickListener.isOver();
    }

    public ClickListener getClickListener() {
        return clickListener;
    }

    public boolean isDisabled() {
        return isDisabled;
    }

    /**
     * When true, the button will not toggle {@link #isChecked()} when clicked
     * and will not fire a {@link ChangeEvent}.
     */
    public void setDisabled(boolean isDisabled) {
        this.isDisabled = isDisabled;
    }

    public void setStyle(ButtonStyle style) {
        if (style == null)
            throw new IllegalArgumentException("style cannot be null.");
        this.style = style;

        Drawable background = style.up;
        if (background == null) {
            background = style.down;
            if (background == null)
                background = style.checked;
        }
        if (background != null) {
            padBottom(background.getBottomHeight());
            padTop(background.getTopHeight());
            padLeft(background.getLeftWidth());
            padRight(background.getRightWidth());
        }
        invalidateHierarchy();
    }

    /**
     * Returns the button's style. Modifying the returned style may not have an
     * effect until {@link #setStyle(ButtonStyle)} is called.
     */
    public ButtonStyle getStyle() {
        return style;
    }

    public void draw(Batch batch, float parentAlpha) {
        validate();

        Drawable background = null;
        float offsetX = 0, offsetY = 0;
        if (isPressed() && !isDisabled) {
            background = style.down == null ? style.up : style.down;
            offsetX = style.pressedOffsetX;
            offsetY = style.pressedOffsetY;
        } else {
            if (isDisabled && style.disabled != null)
                background = style.disabled;
            else if (isChecked && style.checked != null)
                background = (isOver() && style.checkedOver != null) ? style.checkedOver
                        : style.checked;
            else if (isOver() && currentFrame < overAnimation.size) {
                if (overAnimation.get(currentFrame) != null) {
                    background = overAnimation.get(currentFrame);
                }
            } else
                background = style.up;
            offsetX = style.unpressedOffsetX;
            offsetY = style.unpressedOffsetY;
        }
        setBackground(background, false);

        Array<Actor> children = getChildren();
        for (int i = 0; i < children.size; i++)
            children.get(i).moveBy(offsetX, offsetY);
        super.draw(batch, parentAlpha);
        for (int i = 0; i < children.size; i++)
            children.get(i).moveBy(-offsetX, -offsetY);
    }

    public float getPrefWidth() {
        float width = super.getPrefWidth();
        if (style.up != null)
            width = Math.max(width, style.up.getMinWidth());
        if (style.down != null)
            width = Math.max(width, style.down.getMinWidth());
        if (style.checked != null)
            width = Math.max(width, style.checked.getMinWidth());
        return width;
    }

    public float getPrefHeight() {
        float height = super.getPrefHeight();
        if (style.up != null)
            height = Math.max(height, style.up.getMinHeight());
        if (style.down != null)
            height = Math.max(height, style.down.getMinHeight());
        if (style.checked != null)
            height = Math.max(height, style.checked.getMinHeight());
        return height;
    }

    public float getMinWidth() {
        return getPrefWidth();
    }

    public float getMinHeight() {
        return getPrefHeight();
    }

    /**
     * The style for a button, see {@link Button}.
     * 
     * @author mzechner
     */
    static public class ButtonStyle {
        /** Optional. */
        public Drawable up, down, over, checked, checkedOver, disabled;
        /** Optional. */
        public float pressedOffsetX, pressedOffsetY;
        /** Optional. */
        public float unpressedOffsetX, unpressedOffsetY;

        public ButtonStyle() {
        }

        public ButtonStyle(Drawable up, Drawable down, Drawable checked) {
            this.up = up;
            this.down = down;
            this.checked = checked;
        }

        public ButtonStyle(ButtonStyle style) {
            this.up = style.up;
            this.down = style.down;
            this.over = style.over;
            this.checked = style.checked;
            this.checkedOver = style.checkedOver;
            this.disabled = style.disabled;
            this.pressedOffsetX = style.pressedOffsetX;
            this.pressedOffsetY = style.pressedOffsetY;
            this.unpressedOffsetX = style.unpressedOffsetX;
            this.unpressedOffsetY = style.unpressedOffsetY;
        }
    }
}

