package mikera.matrixx.impl;

import java.util.Arrays;
import java.util.List;
import java.util.ArrayList;
// import java.util.HashMap;
// import java.util.HashSet;
// import java.util.Map;
// import java.util.Map.Entry;

import mikera.arrayz.ISparse;
import mikera.matrixx.AMatrix;
import mikera.matrixx.Matrixx;
import mikera.vectorz.AVector;
import mikera.vectorz.Op;
import mikera.vectorz.Vector;
import mikera.vectorz.Vectorz;
import mikera.vectorz.impl.RepeatedElementVector;
import mikera.vectorz.impl.SingleElementVector;
import mikera.vectorz.impl.SparseIndexedVector;
import mikera.vectorz.util.ErrorMessages;
import mikera.vectorz.util.VectorzException;

/**
 * Matrix stored as a collection of normally sparse row vectors.
 * 
 * This format is especially efficient for:
 * - innerProduct() with another matrix, especially one with efficient
 *   column access like SparseColumnMatrix
 * - access via getRow() operation
 * - transpose into SparseColumnMatrix
 * 
 * @author Mike
 * 
 */
public class SparseRowMatrix extends ASparseRCMatrix implements ISparse, IFastRows {
	private static final long serialVersionUID = 8646257152425415773L;

	private static final long SPARSE_ELEMENT_THRESHOLD = 1000L;

	private final AVector emptyRow;

	protected SparseRowMatrix(int rowCount, int columnCount) {
		this(new AVector[rowCount],rowCount,columnCount);
	}

	protected SparseRowMatrix(AVector[] data, int rowCount, int columnCount) {
		super(rowCount,columnCount,data);
        if (data.length != rowCount)
            throw new IllegalArgumentException(ErrorMessages.incompatibleShapes(rowCount, data.length));
		emptyRow=Vectorz.createZeroVector(columnCount);
	}

	protected SparseRowMatrix(AVector... vectors) {
		this(vectors, vectors.length, vectors[0].length());
	}

	protected SparseRowMatrix(List<AVector> data, int rowCount, int columnCount) {
		this(data.toArray(new AVector[0]),rowCount,columnCount);
	}

	protected SparseRowMatrix(List<AVector> data) {
		this(data.toArray(new AVector[0]));
	}

//  	protected SparseRowMatrix(HashMap<Integer,AVector> data, int rowCount, int columnCount) {
//  		super(rowCount,columnCount,data);
//  		emptyColumn=Vectorz.createZeroVector(rowCount);
//  	}

	public static SparseRowMatrix create(int rows, int cols) {
		return new SparseRowMatrix(rows, cols);
	}

	public static SparseRowMatrix create(AVector[] data, int rows, int cols) {
		return new SparseRowMatrix(data, rows, cols);
	}

	public static SparseRowMatrix create(AVector... vecs) {
		return new SparseRowMatrix(vecs);
        // don't validate; user can call validate() if they want it.
	}

	public static SparseRowMatrix create(List<AVector> vecs) {
		return create(vecs.toArray(new AVector[0]));
	}

	public static SparseRowMatrix wrap(AVector[] vecs, int rows, int cols) {
		return create(vecs, rows, cols);
	}

	public static SparseRowMatrix wrap(AVector... vecs) {
		return create(vecs);
	}

	public static SparseRowMatrix create(AMatrix source) {
		int rc = source.rowCount();
		int cc = source.columnCount();
		AVector[] data = new AVector[rc];
		for (int i = 0; i < rc; i++) {
			AVector row = source.getRow(i);
			if (!row.isZero())
			    data[i] = Vectorz.createSparse(row);
		}
		return new SparseRowMatrix(data,rc,cc);
	}

	public static SparseRowMatrix wrap(List<AVector> vecs) {
		return create(vecs);
	}

//	public static SparseRowMatrix wrap(HashMap<Integer, AVector> data, int rows, int cols) {
//		return new SparseRowMatrix(data, rows, cols);
//	}

	@Override
	protected int lineCount() {
		return rows;
	}

	@Override
	protected int lineLength() {
		return cols;
	}

	@Override
	public double get(int i, int j) {
		return getRow(i).get(j);
	}

	@Override
	public void set(int i, int j, double value) {
		checkIndex(i,j);
		unsafeSet(i,j,value);
	}

	@Override
	public double unsafeGet(int row, int column) {
		return getRow(row).unsafeGet(column);
	}

	@Override
	public void unsafeSet(int i, int j, double value) {
		AVector v = unsafeGetVec(i);
		if (v == null) {
			if (value == 0.0)
				return;
			v = SingleElementVector.create(value, j, cols);
		} else if (v.isFullyMutable()) {
			v.set(j, value);
			return;
		} else {
			v = v.sparseClone();
			v.unsafeSet(j, value);
		}
		unsafeSetVec(i, v);
	}

	@Override
	public void set(AMatrix a) {
		checkSameShape(a);
		for (int i=0; i<rows; i++) {
			setRow(i,a.getRow(i));
		}
	}

	@Override
	public void setRow(int i, AVector v) {
		data[i]=v.copy();
	}

	@Override
	public void addAt(int i, int j, double d) {
		if (d==0.0) return;
		AVector v=unsafeGetVec(i);
		if (v.isFullyMutable()) {
			v.addAt(j, d);
		} else {
			v=v.mutable();
			v.addAt(j, d);
			replaceRow(i,v);
		}
	}

	@Override
	public void addToArray(double[] targetData, int offset) {
        for (int i = 0; i < rows; ++i) {
			AVector v = unsafeGetVec(i);
			if (v != null) v.addToArray(targetData, offset+cols*i);
		}
	}

	private AVector ensureMutableRow(int i) {
		AVector v = unsafeGetVec(i);
		if (v == null) {
			AVector nv=SparseIndexedVector.createLength(cols);
            unsafeSetVec(i, nv);
			return nv;
		}
		if (v.isFullyMutable()) return v;
		AVector mv=v.mutable();
		unsafeSetVec(i, mv);
		return mv;
	}

    @Override
    public List<AVector> getColumns() {
        ArrayList<AVector> colList = new ArrayList<AVector>(cols);
        AVector emptyCol = Vectorz.createZeroVector(rows);
        for (int i = 0; i < cols; i++) {
            colList.add(emptyCol);
        }

        for (int i = 0; i < rows; i++) {
            AVector rowVec = unsafeGetVec(i);
            if (null != rowVec) {
                int[] nonZeroCols = rowVec.nonZeroIndices();
                for (int j = 0; j < nonZeroCols.length; j++) {
                    int col = nonZeroCols[j];
                    AVector colVec = colList.get(col);
                    if (emptyCol == colVec) {
                        colVec = SparseIndexedVector.createLength(rows);
                    }
                    colVec.set(i, rowVec.get(col));
                    colList.set(col, colVec);
                }
            }
        }

        return colList;
    }

	@Override
	public AVector getRow(int i) {
		if ((i<0)||(i>=rows)) throw new IndexOutOfBoundsException(ErrorMessages.invalidSlice(this, 0, i));
		AVector v = unsafeGetVec(i);
		if (v == null) return emptyRow;
		return v;
	}

    @Override
	public List<AVector> getSlices() {
        // TODO: Is it acceptable for views to be mixed with
        //       empty row vectors?
        ArrayList<AVector> rowList = new ArrayList<AVector>(rows);
		for (int i = 0; i < rows; i++) {
            AVector v = unsafeGetVec(i);
            if (v == null) {
                rowList.add(emptyRow);
            } else {
                rowList.add(v);
            }
        }
		return rowList;
	}

	@Override
	public AVector getRowView(int i) {
		return ensureMutableRow(i);
	}

	@Override
	public boolean isUpperTriangular() {
		int rc=rowCount();
		for (int i=1; i<rc; i++) {
			if (!getRow(i).isRangeZero(0, i)) return false;
		}
		return true;
	}

	@Override
	public void swapRows(int i, int j) {
		if (i == j)
			return;
		if ((i < 0) || (i >= rows))
			throw new IndexOutOfBoundsException(ErrorMessages.invalidSlice(this, 0, i));
		if ((j < 0) || (j >= rows))
			throw new IndexOutOfBoundsException(ErrorMessages.invalidSlice(this, 0, j));
		AVector a = unsafeGetVec(i);
		AVector b = unsafeGetVec(j);
		unsafeSetVec(i, b);
		unsafeSetVec(j, a);
	}

	@Override
	public void replaceRow(int i, AVector vec) {
		if ((i < 0) || (i >= rows))
			throw new IndexOutOfBoundsException(ErrorMessages.invalidSlice(this, 0, i));
		if (vec.length() != cols)
			throw new IllegalArgumentException(ErrorMessages.incompatibleShape(vec));
        unsafeSetVec(i, vec);
	}

	@Override
	public void add(AMatrix a) {
		checkSameShape(a);
		int rc=rowCount();
		for (int i=0; i<rc; i++) {
			AVector myVec=unsafeGetVec(i);
			AVector aVec=a.getRow(i);
			if (myVec==null) {
				if (!aVec.isZero()) {
					unsafeSetVec(i,aVec.copy());
				}
			} else if (myVec.isFullyMutable()) {
				myVec.add(aVec);
			} else {
				unsafeSetVec(i,myVec.addCopy(aVec));
			}
		}
	}

	@Override
	public void copyRowTo(int i, double[] data, int offset) {
		AVector v=this.unsafeGetVec(i);
		if (v==null) {
			Arrays.fill(data, offset, offset+cols, 0.0);			
		} else {
			v.getElements(data, offset);
		}
	}

	@Override
	public void copyColumnTo(int col, double[] targetData, int offset) {
        for (int i = 0; i < rows; ++i) {
            AVector v = unsafeGetVec(i);
            targetData[offset+i] = (v==null) ? 0.0 : v.unsafeGet(col);
		}		
	}

	@Override
	public SparseColumnMatrix getTransposeView() {
		return SparseColumnMatrix.wrap(data, cols, rows);
	}

	@Override
	public AMatrix multiplyCopy(double a) {
		int n=lineCount();
		AVector[] ndata=new AVector[n];
		for (int i = 0; i < n; ++i) {
            AVector v = unsafeGetVec(i);
            if (v != null)
                ndata[i] = v.multiplyCopy(a);
		}
		return wrap(ndata,rows,cols);
	}

	@Override
	public AVector innerProduct(AVector a) {
		return transform(a);
	}

	@Override
	public AVector transform(AVector a) {
		AVector r=Vector.createLength(rows);
		for (int i=0; i<rows; i++) {
			r.set(i,getRow(i).dotProduct(a));
		}
		return r;
	}

	@Override
	public void applyOp(Op op) {
		boolean stoch = op.isStochastic();
		AVector rr = (stoch) ? null : RepeatedElementVector.create(lineLength(), op.apply(0.0));

		for (int i = 0; i < lineCount(); i++) {
			AVector v = unsafeGetVec(i);
			if (v == null) {
				if (!stoch) {
					unsafeSetVec(i, rr);
					continue;
				}
				v = Vector.createLength(lineLength());
				unsafeSetVec(i, v);
			} else if (!v.isFullyMutable()) {
				v = v.sparseClone();
				unsafeSetVec(i, v);
			}
			v.applyOp(op);
		}
	}

	@Override
	public double[] toDoubleArray() {
		double[] ds=new double[rows*cols];
		// we use adding to array, since rows themselves are likely to be sparse
        for (int i = 0; i < rows; ++i) {
            AVector v = unsafeGetVec(i);
			if (v != null)
                v.addToArray(ds, i*cols);
		}
		return ds;
	}

	@Override
	public AMatrix innerProduct(AMatrix a) {
		if (a instanceof SparseColumnMatrix) {
			return innerProduct((SparseColumnMatrix) a);
		}
		SparseRowMatrix r = Matrixx.createSparse(rows, a.columnCount());

        for (int i = 0; i < rows; ++i) {
			AVector row = unsafeGetVec(i);
            if (! ((row == null) || (row.isZero()))) {
			    r.replaceRow(i,row.innerProduct(a));
            }
		}
		return r;
	}

	/**
	 * Specialised inner product for sparse row matrix multiplied by sparse column matrix. 
	 *  
	 * @param a
	 * @return
	 */
	public SparseRowMatrix innerProduct(SparseColumnMatrix a) {
		// TODO this is probably slow since it operates on the rows of the column matrix?
		// maybe convert to SparseRowMatrix first?
		// new matrix has shape [ this.rows * a.cols ], issue #71
		int acols=a.cols; 
		SparseRowMatrix result = Matrixx.createSparse(rows, acols);

        for (int i = 0; i < rows; ++i) {
        	AVector r=getRow(i);
			AVector nr=r.innerProduct(a);
			result.replaceRow(i, nr);
		}
		return result;
	}

	@Override
	public SparseRowMatrix exactClone() {
		SparseRowMatrix result = new SparseRowMatrix(rows, cols);
        for (int i = 0; i < rows; ++i) {
			AVector row = unsafeGetVec(i);
			if (row != null)
                result.replaceRow(i, row.exactClone());
		}
		return result;
	}

	@Override
	public AMatrix clone() {
		if (this.elementCount() < SPARSE_ELEMENT_THRESHOLD)
			return super.clone();
		return exactClone();
	}

	@Override
	public AMatrix sparse() {
		return this;
	}

	@Override
	public void validate() {
		super.validate();
		for (int i=0; i<rows; i++) {
			if (getRow(i).length()!=cols) throw new VectorzException("Invalid column count at row: "+i);
		}
	}

	@Override
	public boolean equals(AMatrix m) {
		if (m==this) return true;
		if (!isSameShape(m)) return false;
		for (int i=0; i<rows; i++) {
			AVector v=unsafeGetVec(i);
            AVector ov = m.getRow(i);
			if (v==null) {
				if (!ov.isZero()) return false;
			} else {
				if (!v.equals(ov)) return false;
			}
		}
		return true;
	}

	public static AVector innerProduct(AMatrix a, AVector b) {
		// TODO: consider reducing working set?
		return create(a).innerProduct(b);
	}

	public static AMatrix innerProduct(AMatrix a, AMatrix b) {
		// TODO: consider reducing working set?
		return create(a).innerProduct(b);
	}
}

package mikera.vectorz.impl;

import java.util.Arrays;

import mikera.indexz.Index;
import mikera.matrixx.AMatrix;
import mikera.vectorz.AVector;
import mikera.vectorz.util.DoubleArrays;
import mikera.vectorz.util.IntArrays;
import mikera.vectorz.util.VectorzException;


/**
 * Base class containing common implementations for sparse indexed vectors
 * @author Mike
 *
 */
public abstract class ASparseIndexedVector extends ASparseVector {
	private static final long serialVersionUID = -8106136233328863653L;

	public ASparseIndexedVector(int length) {
		super(length);
	}

	abstract double[] internalData();

	abstract Index internalIndex();

	int[] internalIndexArray() {
		return internalIndex().data;
	}

	@Override
	public boolean isZero() {
		return DoubleArrays.isZero(internalData());
	}

	@Override
	public boolean isRangeZero(int start, int length) {
		int end=start+length;
		Index index=internalIndex();
		double[] data=internalData();
		int si=index.seekPosition(start);
		int di=index.seekPosition(end);
		for (int i=si; i<di; i++) {
			if (data[i]!=0.0) return false;
		}
		return true;
	}

	@Override
	public double elementSum() {
		return DoubleArrays.elementSum(internalData());
	}

    @Override
    public void multiply(double factor) {
        double[] data = internalData();
		for (int i = 0; i < data.length; i++) {
			unsafeSet(i,unsafeGet(i)*factor);
		}	
	}

	@Override
	public double magnitudeSquared() {
		return DoubleArrays.elementSquaredSum(internalData());
	}

	@Override
	public long nonZeroCount() {
		return DoubleArrays.nonZeroCount(internalData());
	}

	@Override
	public double dotProduct(double[] data, int offset) {
		double result=0.0;
		double[] tdata=this.internalData();
		int[] ixs=internalIndex().data;
		for (int j=0; j<tdata.length; j++) {
			result+=tdata[j]*data[offset+ixs[j]];
		}
		return result;
	}

	@Override
	public AVector innerProduct(AMatrix a) {
		// we assume sufficient sparsity to make specialised implementation worthwhile?
		// TODO should we go in a different order and calculate via non-zero elements in this? (i.e. avoid iterating over all columns of a)
		int cc=a.columnCount();
		GrowableIndexedVector dest=GrowableIndexedVector.createLength(cc);
		for (int i=0; i<cc; i++) {
			double v=this.dotProduct(a.getColumn(i));
			if (v!=0.0) dest.append(i, v);
		}
		return dest.toSparseIndexedVector();
	}

	@Override
	public final double dotProduct(AVector v) {
		if (v instanceof ADenseArrayVector) return dotProduct((ADenseArrayVector)v);
		if (v instanceof ASparseVector) return dotProduct((ASparseVector)v);
		double result=0.0;
		double[] data=internalData();
		int[] ixs=internalIndexArray();
		for (int j=0; j<data.length; j++) {
			result+=data[j]*v.unsafeGet(ixs[j]);
		}
		return result;
	}

	public final double dotProduct(ASparseVector v) {
		double result=0.0;
		double[] data=internalData();
		int[] ixs=internalIndexArray();
		AVector vvalues=v.nonSparseValues();
		double[] vdata=vvalues.asDoubleArray();
		if (vdata==null) vdata=vvalues.toDoubleArray();
		int[] vixs=v.nonSparseIndex().data;
		if (data.length==0) return 0.0;
		if (vdata.length==0) return 0.0;

		int ti=0;
		int vi=0;
		while ((ti<data.length)&&(vi<vdata.length)) {
			int tv=ixs[ti];
			int vv=vixs[vi];
			if (tv==vv) {
				result+=data[ti]*vdata[vi];
				ti++;
				vi++;
			} else {
				if (tv<vv) {
					ti++;
				} else {
					vi++;
				}
			}
		}

		return result;
	}

	@Override
	public int[] nonZeroIndices() {
		int n=(int)nonZeroCount();
        if (n==0) {
            return new int[0];
        }
		double[] data=internalData();
		Index index=internalIndex();
		int[] ret=new int[n];
		int di=0;
		for (int i=0; i<data.length; i++) {
			if (data[i]!=0.0) ret[di++]=index.get(i);
		}
		if (di!=n) throw new VectorzException("Invalid non-zero index count. Maybe concurrent modification of vector?");
		return ret;
	}

	@Override
	public void addToArray(int offset, double[] array, int arrayOffset, int length) {
		assert((offset>=0)&&(offset+length<=this.length));
		double[] data=internalData();
		Index index=internalIndex();

		int start=index.seekPosition(offset);
		int[] ixs=index.data;
		int dataLength=data.length;
		for (int j=start; j<dataLength; j++) {
			int di=ixs[j]-offset; // index relative to offset
			if (di>=length) return;
			array[arrayOffset+di]+=data[j];
		}
	}

	@Override
	public void addToArray(double[] dest, int offset) {
		double[] data=internalData();
		int[] ixs=internalIndexArray();
		int dataLength=data.length;
		for (int i=0; i<dataLength; i++) {
			dest[offset+ixs[i]]+=data[i];
		}
	}

	@Override
	public void addToArray(double[] dest, int offset, int stride) {
		double[] data=internalData();
		int[] ixs=internalIndexArray();
		for (int i=0; i<data.length; i++) {
			dest[offset+ixs[i]*stride]+=data[i];
		}
	}


	@Override
	public void addMultipleToArray(double factor,int offset, double[] array, int arrayOffset, int length) {
		int aOffset=arrayOffset-offset;

		double[] data=internalData();
		Index index=internalIndex();
		int[] ixs=index.data;
		int start=index.seekPosition(offset);
		for (int i=start; i<data.length; i++) {
			int di=ixs[i];
			// if (di<offset) continue; not needed because of seekPosition!
			if (di>=(offset+length)) return;
			array[di+aOffset]+=factor*data[i];
		}
	}

	@Override
	public void addProductToArray(double factor, int offset, AVector other,int otherOffset, double[] array, int arrayOffset, int length) {
		if (other instanceof ADenseArrayVector) {
			addProductToArray(factor,offset,(ADenseArrayVector)other,otherOffset,array,arrayOffset,length);
			return;
		}
		assert(offset>=0);
		assert(offset+length<=length());

		double[] data=internalData();
		Index index=internalIndex();
		int[] ixs=index.data;
		int dataLength=data.length;
		for (int j=index.seekPosition(offset); j<dataLength; j++) {
			int i =ixs[j]-offset; // index relative to offset
			if (i>=length) return;
			array[i+arrayOffset]+=factor*data[j]*other.get(i+otherOffset);
		}		
	}

	@Override
	public void addProductToArray(double factor, int offset, ADenseArrayVector other,int otherOffset, double[] array, int arrayOffset, int length) {
		assert(offset>=0);
		assert(offset+length<=length());
		double[] otherArray=other.getArray();
		otherOffset+=other.getArrayOffset();

		double[] data=internalData();
		Index index=internalIndex();
		int[] ixs=index.data;
		int dataLength=data.length;
		for (int j=index.seekPosition(offset); j<dataLength; j++) {
			int i =ixs[j]-offset; // index relative to offset
			if (i>=length) return;
			array[i+arrayOffset]+=factor*data[j]*otherArray[i+otherOffset];
		}		
	}

	@Override
	public boolean equalsArray(double[] ds, int offset) {
		double[] data=internalData();
		int[] ixs=internalIndexArray();
		int n=data.length;
		if (n==0) return DoubleArrays.isZero(ds, offset, length);
		int di=0;
		int i=0;
		while (di<n) {
			int t=ixs[di];
			while (i<t) {
				if (ds[offset+i]!=0.0) return false;
				i++;
			}
			if (ds[offset+t]!=data[di]) return false;
			i++;
			di++;
		}
		// check any remaining segment of array
		return DoubleArrays.isZero(ds, offset+i, length-i);
	}

	@Override
	public boolean equals(AVector v) {
		int len=length();
		if (v.length()!=len) return false;

		if (v instanceof ADenseArrayVector) {
			ADenseArrayVector vv=(ADenseArrayVector) v;
			return equalsArray(vv.getArray(),vv.getArrayOffset());
		}

		double[] data=internalData();
		int[] ixs=internalIndexArray();
		int n=ixs.length;
		int start=0;
		for (int i=0; i<n; i++) {
			int pos=ixs[i];
			if (!v.isRangeZero(start, pos-start)) return false;
			if (v.unsafeGet(pos)!=data[i]) return false;
			start=pos+1;
		}
		return v.isRangeZero(start, len-start);
	}

	/**
	 * Create a clone of this sparse indexed vector including the new indexes specified
	 * Intended to allow fast subsequent modification
	 */
	public final SparseIndexedVector cloneIncludingIndices(int [] ixs) {
		Index index=internalIndex();
		int[] nixs = IntArrays.mergeSorted(index.data,ixs);
		double[] data=internalData();
		int nl=nixs.length;
		double[] ndata=new double[nl];
		int si=0;
		for (int i=0; i<nl; i++) {
			int z=index.data[si];
			if (z==nixs[i]) {
				ndata[i]=data[si];
				si++; 
				if (si>=data.length) break;
			}
		}
		return SparseIndexedVector.wrap(length, nixs, ndata);
	}

	@Override 
	public final void getElements(double[] array, int offset) {
		Arrays.fill(array,offset,offset+length,0.0);
		copySparseValuesTo(array,offset);
	}

	@Override public final void copyTo(AVector v, int offset) {
		if (v instanceof ADenseArrayVector) {
			ADenseArrayVector av=(ADenseArrayVector)v;
			getElements(av.getArray(),av.getArrayOffset()+offset);
		}
		v.fillRange(offset,length,0.0);
		double[] data=internalData();
		int[] ixs=internalIndexArray();
		for (int i=0; i<data.length; i++) {
			v.unsafeSet(offset+ixs[i],data[i]);
		}	
	}

	/**
	 * Copy only the sparse values in this vector to a target array. Other values in the target array are unchanged
	 * @param array
	 * @param offset
	 */
	protected final void copySparseValuesTo(double[] array, int offset) {
		Index index=internalIndex();
		int[] ixs = index.data;
		double[] data=internalData();
		for (int i=0; i<data.length; i++) {
			int di=ixs[i];
			array[offset+di]=data[i];
		}	
	}
}

package mikera.vectorz.impl;

import java.util.Arrays;
import java.util.List;

import mikera.arrayz.ISparse;
import mikera.indexz.Index;
import mikera.matrixx.AMatrix;
import mikera.vectorz.AVector;
import mikera.vectorz.util.VectorzException;
import mikera.vectorz.util.ErrorMessages;
import mikera.vectorz.Vectorz;


/**
 * Abstract base class for Sparse vector implementations
 * @author Mike
 *
 */
@SuppressWarnings("serial")
public abstract class ASparseVector extends ASizedVector implements ISparse {

	protected ASparseVector(int length) {
		super(length);
	}

	/**
	 * Returns the number of non-sparse elements in the sparse vector.
	 * @return
	 */
	public abstract int nonSparseElementCount();

	/**
	 * Returns the non-sparse values as a compacted vector view
	 * @return
	 */
	public abstract AVector nonSparseValues();

	@Override
	public abstract Index nonSparseIndex();

	/**
	 * Returns true iff the sparse vector contains the index i 
	 * @param i
	 * @return
	 */
	public abstract boolean includesIndex(int i);

    /**
     * Replaces all values less-than-or-equal to precision with zeros.
     * @param precision
     * @return
     */
    public ASparseVector roundToZero(double precision) {
        throw new VectorzException(ErrorMessages.notYetImplemented());
    }

	// ================================================
	// Superclass methods that must be overridden
	// (superclass implementation is bad for sparse arrays)

	@Override
	public void copyTo(int offset, double[] destData, int destOffset, int length) {
		Arrays.fill(destData, destOffset, destOffset+length, 0.0);
		addToArray(offset, destData, destOffset, length);
	}

	@Override
	public boolean isZero() {
		return nonZeroCount()==0L;
	}

	@Override
	public boolean isView() {
		return false;
	}

	// ================================================
	// standard implementations

	@Override
	public double dotProduct(AVector v) {
		checkSameLength(v);
		double result=0.0;
		Index ni=nonSparseIndex();
		for (int i=0; i<ni.length(); i++) {
			int ii=ni.get(i);
			result+=unsafeGet(ii)*v.unsafeGet(ii);
		}		
		return result;
	}

	@Override
	public final double dotProduct(ADenseArrayVector v) {
		checkSameLength(v);
		double[] array=v.getArray();
		int offset=v.getArrayOffset();
		return dotProduct(array,offset);
	}

	@Override
	public AVector innerProduct(AMatrix m) {
		int cc=m.columnCount();
		int rc=m.rowCount();
		checkLength(rc);
		AVector r=Vectorz.createSparseMutable(cc);
		Index ni=nonSparseIndex();
		for (int i=0; i<ni.length(); i++) {
			int ti=ni.get(i);
			double v=unsafeGet(ti);
			if (v!=0.0) r.addMultiple(m.getRow(ti),v);
		}		
		return r;
	}

	@Override
	public final boolean isSparse() {
		return true;
	}

	@Override
	public void add(AVector v) {
		if (v instanceof ASparseVector) {
			add((ASparseVector)v);
			return;
		}
		super.add(v);
	}

	@Override
	public void addMultiple(AVector src, double factor) {
		add(src.multiplyCopy(factor));
	}

	public abstract void add(ASparseVector v);

    //    public abstract void sub(ASparseVector v);

	@Override
	public List<Double> getSlices() {
		// we prefer a ListWrapper for sparse vectors since it is O(1) to create.
		// downside: causes boxing on individual element accesses
		return new ListWrapper(this);
	}

	@Override
	public double elementProduct() {
		int n=nonSparseElementCount();
		if (n<length) return 0.0;
		return nonSparseValues().elementProduct();
	}

	@Override
	public ASparseVector sparse() {
		return this;
	}

	@Override
	public AVector clone() {
		// TODO: figure out a better heuristic?
		if ((length<20)||(nonSparseElementCount()>(elementCount()*0.25))) return super.clone();
		return SparseIndexedVector.create(this);
	}

	public boolean equals(ASparseVector v) {
		if (v==this) return true;
		if (v.length!=length) return false;

		Index ni=nonSparseIndex();
		for (int i=0; i<ni.length(); i++) {
			int ii=ni.get(i);
			if (unsafeGet(ii)!=v.unsafeGet(ii)) return false;
		}

		Index ri=v.nonSparseIndex();
		for (int i=0; i<ri.length(); i++) {
			int ii=ri.get(i);
			if (unsafeGet(ii)!=v.unsafeGet(ii)) return false;
		}

		return true;
	}

	@Override
	public double[] toDoubleArray() {
		double[] data=new double[length];
		addToArray(data,0);
		return data;
	}

	@Override
	public long nonZeroCount() {
		return nonSparseValues().nonZeroCount();
	}

	@Override
	public boolean equals(AVector v) {
		if (v instanceof ASparseVector) {
			return equals((ASparseVector)v);
		}

		if (v.length()!=length) return false;
		Index ni=nonSparseIndex();
		int n=ni.length();
		AVector nv=nonSparseValues();
		int offset=0;
		for (int i=0; i<n; i++) {
			int ii=ni.get(i);
			if (!v.isRangeZero(offset, ii-offset)) return false;
			if (nv.unsafeGet(i)!=v.unsafeGet(ii)) return false;
			offset=ii+1;
		}
		return v.isRangeZero(offset,length-offset);
	}

	@Override
	public boolean hasUncountable() {
		return nonSparseValues().hasUncountable();
	}

	/**
     * Returns the sum of all the elements raised to a specified power
     * @return
     */
    @Override
    public double elementPowSum(double p) {
        return nonSparseValues().elementPowSum(p);
    }

    /**
     * Returns the sum of the absolute values of all the elements raised to a specified power
     * @return
     */
    @Override
    public double elementAbsPowSum(double p) {
    	return nonSparseValues().elementAbsPowSum(p);
    }
}

package mikera.vectorz.impl;

import mikera.indexz.Index;
import mikera.matrixx.AMatrix;
import mikera.matrixx.impl.AVectorMatrix;
import mikera.matrixx.impl.SparseRowMatrix;
import mikera.matrixx.impl.SparseColumnMatrix;
import mikera.vectorz.AVector;
import mikera.vectorz.Op;
import mikera.vectorz.Vector;
import mikera.vectorz.Vectorz;
import mikera.vectorz.util.DoubleArrays;
import mikera.vectorz.util.ErrorMessages;
import mikera.vectorz.util.IntArrays;
import mikera.vectorz.util.VectorzException;

/**
 * Indexed sparse vector. Efficient for mutable, mostly sparse vectors. 
 * 
 * Maintains a indexed array of elements which may be non-zero. These values *can* also be zero.
 * 
 * WARNING: individual updates of non-indexed elements are O(n) in the number of non-sparse elements. You should not normally
 * perform element-wise mutation on a SparseIndexedVector if performance is a concern
 * 
 * Index must be distinct and sorted.
 * 
 * @author Mike
 *
 */
public class SparseIndexedVector extends ASparseIndexedVector {
	private static final long serialVersionUID = 750093598603613879L;

	private Index index;
	private double[] data;

	private SparseIndexedVector(int length, Index index) {
		this(length,index,new double[index.length()]);
	}

	private SparseIndexedVector(int length, Index index, double[] data) {
		super(length);
		this.index=index;
		this.data=data;
	}

	private SparseIndexedVector(int length, Index index, AVector source) {
		this(length,index,source.toDoubleArray());
	}

	/**
	 * Creates a SparseIndexedVector with the specified index and data values.
	 * Performs no checking - Index must be distinct and sorted.
	 */
	public static SparseIndexedVector wrap(int length, Index index, double[] data) {
		assert(index.length()==data.length);
		assert(index.isDistinctSorted());
		return new SparseIndexedVector(length, index,data);
	}

	/**
	 * Creates a SparseIndexedVector with the specified index and data values.
	 * Performs no checking - Index must be distinct and sorted.
	 */
	public static SparseIndexedVector wrap(int length, int[] indices, double[] data) {
		Index index=Index.wrap(indices);
		assert(index.length()==data.length);
		assert(index.isDistinctSorted());
		return new SparseIndexedVector(length, index,data);
	}

	/**
	 * Creates a SparseIndexedVector using the given sorted Index to identify the indexes of non-zero values,
	 * and a double[] array to specify all the non-zero element values
	 */
	public static SparseIndexedVector create(int length, Index index, double[] data) {
		if (!index.isDistinctSorted()) {
			throw new VectorzException("Index must be sorted and distinct");
		}
		if (!(index.length()==data.length)) {
			throw new VectorzException("Length of index: mismatch woth data");			
		}
		return new SparseIndexedVector(length, index.clone(),DoubleArrays.copyOf(data));
	}

	public static SparseIndexedVector createLength(int length) {
		return new SparseIndexedVector(length, Index.EMPTY,DoubleArrays.EMPTY);
	}

	/**
	 * Creates a SparseIndexedVector using the given sorted Index to identify the indexes of non-zero values,
	 * and a dense vector to specify all the non-zero element values
	 */
	public static SparseIndexedVector create(int length, Index index, AVector data) {
		SparseIndexedVector sv= create(length, index, new double[index.length()]);
		data.getElements(sv.data, 0);
		return sv;
	}

	/** 
	 * Creates a SparseIndexedVector from the given vector, ignoring the zeros in the source.
	 * 
	 */
	public static SparseIndexedVector create(AVector source) {
		if (source instanceof ASparseVector) return create((ASparseVector) source);
		int srcLength = source.length();
		if (srcLength==0) throw new IllegalArgumentException("Can't create a length 0 SparseIndexedVector");
		int[] indexes=source.nonZeroIndices();
		int len=indexes.length;
		double[] vals=new double[len];
		for (int i=0; i<len; i++) {
			vals[i]=source.unsafeGet(indexes[i]);
		}
		return wrap(srcLength,Index.wrap(indexes),vals);
	}

	public static SparseIndexedVector create(ASparseVector source) {
		int length = source.length();
		if (length==0) throw new IllegalArgumentException("Can't create a length 0 SparseIndexedVector");
		Index ixs=source.nonSparseIndex();
		int n=ixs.length();
		double[] vals=new double[n];
		for (int i=0; i<n; i++) {
			vals[i]=source.unsafeGet(ixs.unsafeGet(i));
		}
		return wrap(length,ixs,vals);
	}

	public static SparseIndexedVector create(SparseHashedVector source) {
		int length = source.length();
		if (length==0) throw new IllegalArgumentException("Can't create a length 0 SparseIndexedVector");
		Index ixs=source.nonSparseIndex();
		int n=ixs.length();
		double[] vals=new double[n];
		for (int i=0; i<n; i++) {
			vals[i]=source.unsafeGet(ixs.unsafeGet(i));
		}
		return wrap(length,ixs,vals);
	}

	/** Creates a SparseIndexedVector from a row of an existing matrix */
	public static AVector createFromRow(AMatrix m, int row) {
		if (m instanceof AVectorMatrix) return create(m.getRow(row));
		return create(m.getRow(row));
	}

	@Override
