		assertEquals(sv,sv.cloneIncludingIndices(new int[] {3}));
		assertEquals(sv,sv.cloneIncludingIndices(new int[] {4}));
		assertEquals(sv,sv.cloneIncludingIndices(new int[] {9}));
	}

