		Vector v=Vector.of(0,1,1,0,0,0,1,2);
		SparseIndexedVector sv=SparseIndexedVector.createLength(8);
		assertEquals(0,sv.nonSparseElementCount());
		sv.set(0,2.0);
		assertEquals(1,sv.nonSparseElementCount());
		sv.set(3,0.0);
		assertEquals(1,sv.nonSparseElementCount());
