    /**
     * Converts the ISO code of a region to the code defined in the SAFT file
     * rules
     *
     * @param regionCode
     * @return
     */
    private String getRegionCodeFromISOCode(String regionCode) {
        if (regionCode.equals("PT-20")) {
            return "PT-AC";
        }
        if (regionCode.equals("PT-30")) {
            return "PT-MA";
        }
        return "PT";
    }

