    /**
     * Validates a string, considering the max length of that field that will be
     * assigned and if that field is required
     *
     * @param field
     * @param str
     * @param maxLength
     * @param isRequired
     * @return
     * @throws RequiredFieldNotFoundException
     */
    private String validateString(String field, String str, int maxLength, boolean isRequired)
            throws RequiredFieldNotFoundException {
        if (isRequired && (str == null || str.length() == 0)) {
            throw new RequiredFieldNotFoundException(this.context + field);
        } else {
            if (str != null && str.length() > maxLength) {
                String original = str;
                str = str.substring(0, maxLength);
                log.debug("the field {} has been truncated from '{}' to '{}'.", this.context + field, original, str);
            }
            return (str == null) ? new String() : str.trim();
        }
    }

    /**
     * Validates an integer, considering the max length of that field that will
     * be assigned and if that field is required
     *
     * @param field
     * @param str
     *        - a string that represents an integer
     * @param maxLength
     * @param isRequired
     * @return
     * @throws RequiredFieldNotFoundException
     */
    private int validateInteger(String field, String str, int maxLength, boolean isRequired)
            throws RequiredFieldNotFoundException {
        return Integer.parseInt(this.validateString(field, str, maxLength, isRequired));
    }

    /**
     * Validates a BigInteger, considering the max length of that field that
     * will be assigned and if that field is required
     *
     * @param field
     * @param str
     *        - a string that represents a BigInteger
     * @param maxLength
     * @param isRequired
     * @return
     * @throws RequiredFieldNotFoundException
     */
    private BigInteger validateBigInteger(String field, String str, int maxLength, boolean isRequired)
            throws RequiredFieldNotFoundException {
        return new BigInteger(this.validateString(field, str, maxLength, isRequired));
    }

    /**
     * Validates a decimal number, limiting it to 2 decimal places and rounding
     * int
     *
     * @param bd
     * @return
     */
    private BigDecimal validateBigDecimal(BigDecimal bd) {
        return bd.setScale(BillyMathContext.SCALE, this.mc.getRoundingMode());
    }

    /**
     * Gets the today's date
     *
     * @return
     * @throws DatatypeConfigurationException
     */
    private XMLGregorianCalendar getXMLGregorianCalendarNow() throws DatatypeConfigurationException {
        return this.formatDate(new Date());
    }

    /**
     * Returns a date in the format YYYY-MM-dd
     *
     * @param date
     * @return
     * @throws DatatypeConfigurationException
     */
    private XMLGregorianCalendar formatDate(Date date) throws DatatypeConfigurationException {
        Calendar cal = Calendar.getInstance();
        cal.setTime(date);
        return DatatypeFactory.newInstance().newXMLGregorianCalendarDate(cal.get(Calendar.YEAR),
                (cal.get(Calendar.MONTH) + 1), cal.get(Calendar.DAY_OF_MONTH), DatatypeConstants.FIELD_UNDEFINED);
    }

    /**
     * Returns a datetime in the format YYYY-MM-ddThh-mm-ss
     *
     * @param date
     * @return
     * @throws DatatypeConfigurationException
     */
    private XMLGregorianCalendar formatDateTime(Date date) throws DatatypeConfigurationException {
        Calendar cal = Calendar.getInstance();
        cal.setTime(date);
        return DatatypeFactory.newInstance().newXMLGregorianCalendar(cal.get(Calendar.YEAR),
                (cal.get(Calendar.MONTH) + 1), cal.get(Calendar.DAY_OF_MONTH), cal.get(Calendar.HOUR_OF_DAY),
                cal.get(Calendar.MINUTE), cal.get(Calendar.SECOND), DatatypeConstants.FIELD_UNDEFINED,
                DatatypeConstants.FIELD_UNDEFINED);
    }

    /**
     * Returns a field (the month or the year) of a date
     *
     * @param date
     * @param field
     * @return
     */
    private int getDateField(Date date, int field) {
        Calendar issueDate = Calendar.getInstance();
        issueDate.setTime(date);
        return issueDate.get(field);
    }
}

