    /*************
     * DOCUMENTS *
     *************/
    /**
     * Converts the document state to an acronym according to the SAFT file
     * rules
     *
     * @param document
     * @return
     * @throws InvalidDocumentStateException
     * @throws DatatypeConfigurationException
     * @throws RequiredFieldNotFoundException
     */
    private DocumentStatus getDocumentStatus(PTGenericInvoiceEntity document)
            throws InvalidDocumentStateException, DatatypeConfigurationException, RequiredFieldNotFoundException {
        DocumentStatus status = new DocumentStatus();

        if (document.isCancelled()) {
            status.setInvoiceStatus("A");
        } else if (document.isBilled()) {
            status.setInvoiceStatus("F");
        } else if (document.isSelfBilled()) {
            status.setInvoiceStatus("S");
        } else {
            status.setInvoiceStatus("N");
        }

        status.setInvoiceStatusDate(this.formatDateTime(document.getDate()));
        if (document.getChangeReason() != null) {
            status.setReason(this.validateString("Reason", document.getChangeReason(), this.MAX_LENGTH_50, false));
        }
        status.setSourceID(document.getSourceId());
        status.setSourceBilling(SAFTPTSourceBilling.valueOf(document.getSourceBilling().toString()));
        return status;
    }

    @SuppressWarnings("unchecked")
    private List<PaymentMethod> getPaymentsList(PTGenericInvoiceEntity document)
            throws RequiredFieldNotFoundException, InvalidPaymentMechanismException, DatatypeConfigurationException {

        if (document.getPayments() != null) {
            List<PaymentMethod> payments = new ArrayList<>();
            for (com.premiumminds.billy.core.services.entities.Payment p : document.getPayments()) {
                PaymentMethod payment = new PaymentMethod();

                payment.setPaymentMechanism(this.validateString("PaymentMechanism",
                        this.getPaymentMechanism((Enum<PaymentMechanism>) p.getPaymentMethod()), this.MAX_LENGTH_2,
                        true));
                payment.setPaymentAmount(this.validateBigDecimal(((PTPayment) p).getPaymentAmount()));
                payment.setPaymentDate(this.formatDate(p.getPaymentDate()));
                payments.add(payment);
            }

            return payments;
        }
        return null;
    }

    /**
     * Converts the payment mechanism to an acronym according to the SAFT file
     * rules
     *
     * @param pm
     * @return
     * @throws InvalidPaymentMechanismException
     */
    private String getPaymentMechanism(Enum<PaymentMechanism> pm) throws InvalidPaymentMechanismException {
        switch ((PaymentMechanism) pm) {
            case CASH:
                return "NU";
            case CHECK:
                return "CH";
            case DEBIT_CARD:
                return "CD";
            case CREDIT_CARD:
                return "CC";
            case BANK_TRANSFER:
                return "TB";
            case RESTAURANT_TICKET:
                return "TR";
            case COMPENSATION:
                return "CS";
            case COMMERCIAL_LETTER:
                return "LC";
            case ATM:
                return "MB";
            case EXCHANGE:
                return "PR";
            case ELECTRONIC_MONEY:
                return "DE";
            default:
                throw new InvalidPaymentMechanismException(pm.toString());
        }
    }

    /***********************
     * ADDRESSES & REGIONS *
     ***********************/
    /**
     * Constructs an AddressStructures that is used in almost every fields of
     * SAFT file that represent addresses
     *
     * @param addressEntity
     * @return
     * @throws RequiredFieldNotFoundException
     */
    private AddressStructure generateAddressStructure(PTAddressEntity addressEntity)
            throws RequiredFieldNotFoundException {
        AddressStructure address = new AddressStructure();

        if ((this.optionalParam =
                this.validateString("BuildingNumber", addressEntity.getNumber(), this.MAX_LENGTH_10, false))
